 "content": "def transform(grid):
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # The two same-row markers define a horizontal spine; extend each other marker vertically to it.
    rows={r for r,c in pts}
    spine=next(r for r in rows if sum(rr==r for rr,cc in pts)==2)
    cols=[c for r,c in pts if r==spine]
    out=[row[:] for row in grid]
    for r,c in pts:
        if r==spine: continue
        for rr in range(min(r,spine),max(r,spine)+1):
            if out[rr][c]==0: out[rr][c]=3
    for c in range(min(cols),max(cols)+1):
        if out[spine][c]==0: out[spine][c]=3
    return out
